import{f as l,o as r,c as e,ah as i}from"./chunks/framework.5bt9HFMa.js";const x=JSON.parse('{"title":"操作系统文件管理","description":"","frontmatter":{},"headers":[],"relativePath":"series/操作系统/04-文件.md","filePath":"series/操作系统/04-文件.md","lastUpdated":1777791679000}'),a={name:"series/操作系统/04-文件.md"};function n(o,t,s,g,d,h){return r(),e("div",null,t[0]||(t[0]=[i('<h1 id="操作系统文件管理" tabindex="-1">操作系统文件管理 <a class="header-anchor" href="#操作系统文件管理" aria-label="Permalink to &quot;操作系统文件管理&quot;">​</a></h1><p>文件管理是操作系统中负责管理计算机文件系统的部分，主要涉及文件的逻辑结构、物理结构、目录管理、存储空间管理以及文件的共享与保护。</p><hr><h2 id="一、文件系统基础" tabindex="-1">一、文件系统基础 <a class="header-anchor" href="#一、文件系统基础" aria-label="Permalink to &quot;一、文件系统基础&quot;">​</a></h2><h3 id="_1-文件的概念" tabindex="-1">1. 文件的概念 <a class="header-anchor" href="#_1-文件的概念" aria-label="Permalink to &quot;1. 文件的概念&quot;">​</a></h3><ul><li><strong>定义</strong>：是以计算机硬盘为载体的存储在计算机上的信息集合。</li><li><strong>属性</strong>：文件名、标识符、类型、位置、大小、保护信息、时间日期等。</li><li><strong>基本操作</strong>：创建、删除、读、写、截断、打开、关闭。</li></ul><h3 id="_2-文件的逻辑结构" tabindex="-1">2. 文件的逻辑结构 <a class="header-anchor" href="#_2-文件的逻辑结构" aria-label="Permalink to &quot;2. 文件的逻辑结构&quot;">​</a></h3><p>指在用户看来，文件内部的数据是如何组织的。</p><ul><li><strong>无结构文件（流式文件）</strong>：文件内部的数据就是一系列二进制流或字符流。如 <code>.txt</code>, <code>.exe</code>。</li><li><strong>有结构文件（记录式文件）</strong>：由一组相似的记录组成。 <ul><li><strong>顺序文件</strong>：记录按顺序排列。</li><li><strong>索引文件</strong>：为变长记录建立索引表。</li><li><strong>索引顺序文件</strong>：分组索引，结合了前两者优点。</li></ul></li></ul><h3 id="_3-目录结构" tabindex="-1">3. 目录结构 <a class="header-anchor" href="#_3-目录结构" aria-label="Permalink to &quot;3. 目录结构&quot;">​</a></h3><ul><li><strong>FCB (文件控制块)</strong>：包含文件基本信息（文件名、物理地址、保护信息等），是文件存在的标志。</li><li><strong>目录结构形式</strong>： <ul><li><strong>单级目录</strong>：所有文件在一个表中，不允许重名。</li><li><strong>两级目录</strong>：主文件目录 (MFD) + 用户文件目录 (UFD)。</li><li><strong>树形目录</strong>：现代 OS 通用，支持多级目录，绝对路径/相对路径。</li><li><strong>无环图目录</strong>：在树形基础上允许共享（通过链接）。</li></ul></li></ul><hr><h2 id="二、文件系统实现-物理结构" tabindex="-1">二、文件系统实现（物理结构） <a class="header-anchor" href="#二、文件系统实现-物理结构" aria-label="Permalink to &quot;二、文件系统实现（物理结构）&quot;">​</a></h2><p>指文件数据在物理存储设备上是如何存放的。</p><h3 id="_1-文件分配方式" tabindex="-1">1. 文件分配方式 <a class="header-anchor" href="#_1-文件分配方式" aria-label="Permalink to &quot;1. 文件分配方式&quot;">​</a></h3><ul><li><strong>连续分配</strong>： <ul><li>每个文件在磁盘上占有一组连续的块。</li><li><strong>优点</strong>：支持随机访问，顺序读写速度最快。</li><li><strong>缺点</strong>：产生外部碎片，文件扩展困难。</li></ul></li><li><strong>链接分配</strong>： <ul><li><strong>隐式链接</strong>：目录项指向第一块，块内指向下一块。无碎片，扩展容易；但只支持顺序访问。</li><li><strong>显式链接 (FAT)</strong>：指针存放在内存的一张文件分配表 (FAT) 中。支持随机访问。</li></ul></li><li><strong>索引分配</strong>： <ul><li>每个文件有一张索引表（索引块），记录逻辑块到物理块的映射。</li><li><strong>优点</strong>：支持随机访问，无外部碎片。</li><li><strong>缺点</strong>：索引表占用额外空间。</li><li><strong>混合索引 (Unix/Linux)</strong>：直接地址 + 一级间接 + 二级间接...（解决大文件问题）。</li></ul></li></ul><h3 id="_2-空闲空间管理" tabindex="-1">2. 空闲空间管理 <a class="header-anchor" href="#_2-空闲空间管理" aria-label="Permalink to &quot;2. 空闲空间管理&quot;">​</a></h3><ul><li><strong>空闲表法</strong>：记录所有空闲区（起始块号，长度）。</li><li><strong>空闲链表法</strong>：将空闲块链在一起。</li><li><strong>位示图法 (Bit Map)</strong>：用二进制位 0/1 表示块空闲/占用。易于在内存中操作。</li><li><strong>成组链接法 (Unix)</strong>：适合大型文件系统，结合了链表和索引的特点。</li></ul><hr><h2 id="三、磁盘组织与管理" tabindex="-1">三、磁盘组织与管理 <a class="header-anchor" href="#三、磁盘组织与管理" aria-label="Permalink to &quot;三、磁盘组织与管理&quot;">​</a></h2><h3 id="_1-磁盘结构" tabindex="-1">1. 磁盘结构 <a class="header-anchor" href="#_1-磁盘结构" aria-label="Permalink to &quot;1. 磁盘结构&quot;">​</a></h3><ul><li><strong>物理地址</strong>：(柱面号, 盘面号, 扇区号)。</li><li><strong>读写时间</strong> = 寻道时间 (最慢) + 旋转延迟 + 传输时间。</li></ul><h3 id="_2-磁盘调度算法" tabindex="-1">2. 磁盘调度算法 <a class="header-anchor" href="#_2-磁盘调度算法" aria-label="Permalink to &quot;2. 磁盘调度算法&quot;">​</a></h3><p>目标是减少<strong>寻道时间</strong>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">算法</th><th style="text-align:left;">名称</th><th style="text-align:left;">描述</th><th style="text-align:left;">特点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FCFS</strong></td><td style="text-align:left;">先来先服务</td><td style="text-align:left;">按请求顺序</td><td style="text-align:left;">公平，但性能差。</td></tr><tr><td style="text-align:left;"><strong>SSTF</strong></td><td style="text-align:left;">最短寻找时间优先</td><td style="text-align:left;">找离当前磁头最近的</td><td style="text-align:left;">性能好，但可能导致远端请求“饥饿”。</td></tr><tr><td style="text-align:left;"><strong>SCAN</strong></td><td style="text-align:left;">扫描算法 (电梯)</td><td style="text-align:left;">磁头单向移动到头，再反向</td><td style="text-align:left;">解决饥饿，但在两端请求密度不均。</td></tr><tr><td style="text-align:left;"><strong>C-SCAN</strong></td><td style="text-align:left;">循环扫描</td><td style="text-align:left;">单向移动，到头直接回起点</td><td style="text-align:left;">响应时间更均匀。</td></tr><tr><td style="text-align:left;"><strong>LOOK / C-LOOK</strong></td><td style="text-align:left;"></td><td style="text-align:left;">SCAN/C-SCAN 的优化</td><td style="text-align:left;">不走到端点，只走到最远的请求处。</td></tr></tbody></table><hr><h2 id="四、文件共享与保护" tabindex="-1">四、文件共享与保护 <a class="header-anchor" href="#四、文件共享与保护" aria-label="Permalink to &quot;四、文件共享与保护&quot;">​</a></h2><h3 id="_1-文件共享" tabindex="-1">1. 文件共享 <a class="header-anchor" href="#_1-文件共享" aria-label="Permalink to &quot;1. 文件共享&quot;">​</a></h3><ul><li><strong>硬链接 (Hard Link)</strong>： <ul><li>基于索引节点 (Inode)。</li><li>多个文件名指向同一个 Inode。</li><li>只有引用计数为 0 时才真正删除文件。</li></ul></li><li><strong>软链接 (Symbolic Link)</strong>： <ul><li>特殊类型的文件，内容是另一个文件的路径。</li><li>原文件删除，软链接失效（悬空）。</li></ul></li></ul><h3 id="_2-文件保护" tabindex="-1">2. 文件保护 <a class="header-anchor" href="#_2-文件保护" aria-label="Permalink to &quot;2. 文件保护&quot;">​</a></h3><ul><li><strong>口令保护</strong>：文件关联口令。</li><li><strong>加密保护</strong>：对文件内容加密。</li><li><strong>访问控制</strong>： <ul><li><strong>访问控制表 (ACL)</strong>。</li><li><strong>用户/组/其他 (User/Group/Other)</strong> 权限位 (rwx) —— Linux 常用。</li></ul></li></ul><hr><blockquote><p><strong>总结</strong></p><ul><li><strong>逻辑结构</strong>：流式 vs 记录式。</li><li><strong>物理分配</strong>：连续 vs 链接 (FAT) vs 索引 (Inode)。</li><li><strong>磁盘调度</strong>：SCAN / C-SCAN 是主流。</li><li><strong>核心概念</strong>：FCB, Inode, FAT, 目录树。</li></ul></blockquote>',33)]))}const c=l(a,[["render",n]]);export{x as __pageData,c as default};
